


export type WebhookEndpoint = { /** A dated API version pins this endpoint. The value default follows the endpoint owner's merchant default at delivery time, including retries. Deliveries never use a newer version than the event's recorded version. */ "api_version": string; /** RFC3339 timestamp. Format: date-time. */ "api_version_changed_at"?: string; "api_version_previous"?: string; /** RFC3339 timestamp. Format: date-time. */ "created_at"?: string; "description"?: string; "enabled": boolean; /** Event types this endpoint receives. Empty means all merchant-owned events. For partner_app sources, empty defaults to all app lifecycle events. For installed_merchants sources, provide at least one installed-merchant event. */ "enabled_events": Array<string>; /** Event sources this endpoint receives. Defaults to merchant. Use partner_app for app lifecycle events and installed_merchants for events from merchants that installed the partner app. */ "event_sources"?: Array<"merchant" | "partner_app" | "installed_merchants" | (string & {})>; /** Partner-source delivery mode. Valid values are test, live, and both. Mode applies to installed_merchants events; partner_app lifecycle events require both. */ "mode"?: "test" | "live" | "both" | (string & {}); /** Partner app that owns partner_app or installed_merchants event sources. */ "partner_app_id"?: string; "secret"?: string; /** RFC3339 timestamp. Format: date-time. */ "updated_at"?: string; "url": string; "webhook_endpoint_id": string; };
